package com.hibernate.ecommerce.controller;import com.hibernate.ecommerce.dto.ProductDTO;import com.hibernate.ecommerce.service.IProductService;import jakarta.validation.Valid;import jakarta.validation.constraints.Positive;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.support.ServletUriComponentsBuilder;import java.net.URI;import java.util.List;@RestController@RequestMapping("/v1/api/product")public class ProductController {    private final IProductService iProductService;    public ProductController(IProductService iProductService) {        this.iProductService = iProductService;    }    @PostMapping("/insert")    public ResponseEntity<ProductDTO> insertProduct(@Valid @RequestBody ProductDTO dto){        ProductDTO saved = iProductService.addProduct(dto);        URI location = ServletUriComponentsBuilder                .fromCurrentRequest()                .path("/{id}")                .buildAndExpand(saved.getId())                .toUri();        return ResponseEntity.created(location).body(saved);    }    @GetMapping("/search/{id}")    public ResponseEntity<ProductDTO> findProductById(@PathVariable @Positive Long id){        return ResponseEntity.ok(iProductService.findProductById(id));    }    @GetMapping("/search")    public ResponseEntity<List<ProductDTO>> findFilterOrAll(@RequestParam String name){        return ResponseEntity.ok(iProductService.findOptionalAll(name));    }    @PutMapping("/update/{id}")    public ResponseEntity<ProductDTO> updateProduct(@PathVariable @Positive Long id, @Valid @RequestBody ProductDTO dto){        return ResponseEntity.ok(iProductService.updateProduct(id, dto));    }    @DeleteMapping("/delete/{id}")    public ResponseEntity<Void> deleteProductById(@PathVariable @Positive Long id){        iProductService.deleteProduct(id);        return ResponseEntity.noContent().build();    }}